Method.Implementation:
set x12DocId = x12Doc.%Id()
set tPrelationDocumentId = 0
set parentErrorMsg = ""
set fullErrorMsg = "OK"

$$$TRACE( "GetTpInformation " _ x12DocId _ ", 250 bytes: " _ $E(x12Doc.OutputToString("|:^~" _$CHAR(13) _$CHAR(10)), 1, 250) )
set tSC= $$$OK
set InterchangeSenderID ="",  InterchangeReceiverID = ""
if (x12Doc.%Extends("EnsLib.EDI.X12.Document"))
 {
	   set x12Doc.DocType = "HIPAA_5010:Interchange:Group"
	   Set tSC =x12Doc.BuildMap()

	   set InterchangeCtrlNum = x12Doc.GetValueAt("ISA:InterchangeControlNumber")
	   set InterchangeSenderID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeSenderID"), "<>W")
	   set InterchangeReceiverID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeReceiverID"), "<>W")
	   set InterchangeControlVersionNum = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeControlVersionNum"), "<>W")
	   set isaDocType = x12Doc.DocType

	   if ( (InterchangeSenderID ="") ||  (InterchangeReceiverID = "") )
	   {
		   set fullErrorMsg = "Interchange values are empty, Invalid X12: " _ x12Doc.OutputToString()
		   QUIT $$$ERROR($$$EnsEDIX12ErrGeneral, "Invalid X12")
	   }
	   $$$TRACE("GetTpInformation ISA: " _ isaDocType _", " _ InterchangeSenderID _ " -> " _InterchangeReceiverID _ " , Version: " _InterchangeControlVersionNum )

	   try
	   {

		   Set k1="",tSC=1,k2=""
		   set numGS = 0, numSTs = 0, numRecs = 0, transactionCode = 0
		   set nxt = x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans)
		   if ($$$ISERR(tSCTrans))
		   {

			   // Check if this is TA1
			   set seg = x12Doc.FindSegment("TA1", .ind, .stat)
  				if ( ($$$ISOK(stat)) && ($IsObject(seg)))
  				{
	  				set parentErrorMsg = seg.Name _ "*" _  seg.GetValueAt("4") _ "*" _ seg.GetValueAt("5")
	  				set tpObj = ##class(IHC.TPManage.TPrelationDocument).%New()
					 SET tpObj.x12Data = x12DocId
					 SET tpObj.SessionId = sesId
					 set tpObj.FileName = x12Doc.Source
					 set tpObj.createDtTm = $ZDATETIME($HOROLOG,3, 1)
					 set tpObj.NumOfGSs = numGS
					 set tpObj.NumOfSTs = numSTs
					 set tpObj.NumOfTrns = numRecs

					 set tpObj.INTERCHANGECONTROLNUMBER = InterchangeCtrlNum
				     set tpObj.ISARECEIVERTPID = InterchangeReceiverID
				     set tpObj.ISASENDERTPID = InterchangeSenderID

				     set tpObj.statusDetails = fullErrorMsg
					 set tpObj.status = "Data Error"
				     Do tpObj.%Save()
				     $$$TRACE("Saved IHC.TPManage.TPrelationDocument: " _ tpObj.%Id())
				     set tPrelationDocumentId = tpObj.%Id()

  				}
			   QUIT
		   }
		    Set k1=x12Doc.NextChild(k1,nxt)
		    while ($IsObject(k1))
		    {
			    set numGS = numGS + 1
				// WRITE !, "k1: " _ k1 _ ", Doc: " _ k1.DocType 

				If ""=k1.DocType {
					Set tDocType = k1.resolveChildDocType()
					$$$TRACE( "resolveChildDocType k1: " _ k1 _ ", Doc: " _ tDocType)
					Set tSC =k1.PokeDocType(tDocType)
				}

		 		 set applicationSendersCode = $ZSTRIP(k1.GetValueAt("GS:ApplicationSendersCode") , "<>W")
				 set applicationReceiversCode = $ZSTRIP(k1.GetValueAt("GS:ApplicationReceiversCode"), "<>W")
				 set x12Version = k1.GetValueAt("GS:VersionReleaseIndustryIdenti")
				 set groupVersion = "V" _ $ZSTRIP(x12Version, "<", "0")
				 set grpCtrlNum = $ZSTRIP(k1.GetValueAt("GS:GroupControlNumber"), "<>W")
				 set grpDocType = k1.DocType
				// WRITE !,  "GS: " _ k1.DocType _ ", GS Sender" _ applicationSendersCode _ " -> " _ applicationReceiversCode_ " , GS Version: " _ groupVersion
				Do ..ReadST(x12Doc, k1, .numSTs, .numRecs, .transactionCode, .parentErrorMsg)
				Set k1=x12Doc.NextChild(k1,x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans))
		    }

		    set errorMsg = "X12 values found"

		 WRITE !, "Create IHC.TPManage.TPrelationDocument" 
		 #dim tpObj As IHC.TPManage.TPrelationDocument;
		 set tpObj = ##class(IHC.TPManage.TPrelationDocument).%New()

		 SET tpObj.x12Data = x12DocId
		 SET tpObj.SessionId = sesId
		 set tpObj.FileName = x12Doc.Source
		 set tpObj.createDtTm = $ZDATETIME($HOROLOG,3, 1)
		 set tpObj.NumOfGSs = numGS
		 set tpObj.NumOfSTs = numSTs
		 set tpObj.NumOfTrns = numRecs
		 set tpObj.TransactionCode = transactionCode
	     set tpObj.ISARECEIVERTPID = InterchangeReceiverID
	     set tpObj.ISASENDERTPID = InterchangeSenderID
		 set tpObj.GRPRECEIVERTPID = applicationReceiversCode  
	     set tpObj.GRPSENDERTPID = applicationSendersCode
	     set tpObj.TransactionVersion = x12Version

		 if ((transactionCode '= "999") || (checkRel = 1))
		 {

			 set tSC = ..ItfFindInterchageLink(isaDocType, InterchangeSenderID, InterchangeReceiverID, groupVersion, mode, direction, tpObj, .errorMsg)
			 set fullErrorMsg = errorMsg
			 WRITE !, "From InterchageLink "_ tSC
			 if ($$$ISERR(tSC))
			 {
				 Do ..ItfFindTPIDS(InterchangeSenderID, .errorMsg)
				 set fullErrorMsg = fullErrorMsg _ errorMsg
				 Do ..ItfFindTPIDS(InterchangeReceiverID, .errorMsg)
				 set fullErrorMsg = fullErrorMsg _ errorMsg
				 set tpObj.statusDetails = fullErrorMsg
				 set tpObj.status = "TP Relationship not found"
				 Do tpObj.%Save()
				 WRITE !, "IHC.TPManage.TPrelationDocument Id: " _ tpObj.%Id()
			 }
			 else
			 {
				 set tSC = ..ItfFindGroupLink(grpDocType, applicationSendersCode, applicationReceiversCode, groupVersion, mode, direction, tpObj, .errorMsg)
				 set fullErrorMsg =  errorMsg _ ", " _ fullErrorMsg
				 if ($$$ISERR(tSC))
				 {
					 set tSC1 = ..ItfFindTPIDS(applicationSendersCode, .errorMsg)
					 if ($$$ISERR(tSC1))
					 {
					    set fullErrorMsg = errorMsg _ ", " _  fullErrorMsg
					 }
					 set tSC1 = ..ItfFindTPIDS(applicationReceiversCode, .errorMsg)
					 if ($$$ISERR(tSC1))
					 {
					   set fullErrorMsg = errorMsg _ ", " _  fullErrorMsg
					 }
					 set tpObj.statusDetails = fullErrorMsg
					 set tpObj.status = "TP GroupLink not found"
					 Do tpObj.%Save()
					 WRITE !, "IHC.TPManage.TPrelationDocument Id: " _ tpObj.%Id()
				 }
			 }
		 }
		 if ($$$ISOK(tSC))
		 {
				set fullErrorMsg = "OK" _ ", " _  fullErrorMsg
				 set tpObj.status = "OK"
				 set tSC = tpObj.%Save()
				 IF $$$ISOK(tSC) {  
	                $$$TRACE( " TPrelationDocument saved: " _ tpObj.%Oid())
	                $$$TRACE("IHC.TPManage.TPrelationDocument Id: " _ tpObj.%Id())
	             }
	  			 ELSE { 
	  			 	$$$LOGERROR("Save TPrelationDocument failed, " _ tSC)
	  			  }


		 }
		 set tPrelationDocumentId = tpObj.%Id()
	 } catch err
	 {
		 set tSC= $$$ERROR($$$EnsEDIX12ErrGeneral, "Exception in GetTpInformation " _ err)
	 }
 }
 else
 {
	 $$$TRACE("Invalid doc type")
	 set tSC= $$$ERROR($$$EnsEDIX12ErrGeneral, "Doctype is not valid: "_ x12Doc.DocType)
 }
 $$$TRACE("GetTpInformation return: " _ tPrelationDocumentId)
 return tSC

set x12DocId = x12Doc.%Id()
set tPrelationDocumentId = 0
set hz = $HOROLOG

 SET dateint=$PIECE(hz,",",1) - numberDays
 SET timeint=$PIECE(hz,",",2)
 set recDt = $ZDATETIME(dateint_","_timeint,  3, 1)

 $$$TRACE("Check duplicates from " _ recDt _", Num days: " _ numberDays)



$$$TRACE( "IsDuplicate " _ x12DocId _ ", 250 bytes: " _ $E(x12Doc.OutputToString("|:^~" _$CHAR(13) _$CHAR(10)), 1, 250) )
set tSC= $$$OK
set InterchangeSenderID ="",  InterchangeReceiverID = ""
if (x12Doc.%Extends("EnsLib.EDI.X12.Document"))
 {
	   set x12Doc.DocType = "HIPAA_5010:Interchange:Group"
	   Set tSC =x12Doc.BuildMap()

	   set InterchangeCtrlNum = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeControlNumber"), "<>W")
	   set InterchangeSenderID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeSenderID"), "<>W")
	   set InterchangeReceiverID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeReceiverID"), "<>W")

	   if ( (InterchangeSenderID ="") ||  (InterchangeReceiverID = "") )
	   {
		   set fullErrorMsg = "Interchange values are empty, Invalid X12: " _ x12Doc.OutputToString()
		   QUIT $$$ERROR($$$EnsEDIX12ErrGeneral, "Invalid X12")
	   }
	   $$$TRACE("IsDuplicateISA: " _ InterchangeSenderID _ " -> " _InterchangeReceiverID _ " , Ctrl# " _InterchangeCtrlNum )

	   try
	   {

		   Set k1="",tSC=1,k2=""
		   set numGS = 0, numSTs = 0, numRecs = 0, transactionCode = 0
		   set nxt = x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans)
		   if ($$$ISERR(tSCTrans))
		   {
			   QUIT
		   }
		    Set k1=x12Doc.NextChild(k1,nxt)
		    while ($IsObject(k1))
		    {
			    set numGS = numGS + 1

				If ""=k1.DocType {
					Set tDocType = k1.resolveChildDocType()
					$$$TRACE( "resolveChildDocType k1: " _ k1 _ ", Doc: " _ tDocType)
					Set tSC =k1.PokeDocType(tDocType)
				}

		 		 set applicationSendersCode = $ZSTRIP(k1.GetValueAt("GS:ApplicationSendersCode") , "<>W")
				 set applicationReceiversCode = $ZSTRIP(k1.GetValueAt("GS:ApplicationReceiversCode"), "<>W")
				 set grpCtrlNum = $ZSTRIP(k1.GetValueAt("GS:GroupControlNumber"), "<>W")

				$$$TRACE(  "GS Sender: " _ applicationSendersCode _ " -> " _ applicationReceiversCode_ " , GS Ctrl: " _ grpCtrlNum _", GS #" _numGS)
				Do ..ReadST(x12Doc, k1, .numSTs, .numRecs, .transactionCode, .parentErrorMsg)
				Set k1=x12Doc.NextChild(k1,x12Doc.GetSegmentIndex("GroupDocsRef",.tSCTrans))
		    }


		 $$$TRACE(  "ST: " _ transactionCode _", ST #: " _ numSTs _", Trns # " _ numRecs)
		 set tblNm = "IHC_X12.Data" _ transactionCode

		 set sqlStr = "Select ID from " _ tblNm _
		 " where InterchangeControlNumber  = ? AND InterchangeReceiverID = ? "_
		 " AND InterchangeSenderID = ? "_
		 " AND GroupControlNumber = ? AND  ApplicationReceiversCode = ? "_
		 " AND ApplicationSendersCode  = ? " _
		 " AND ReceiptDtTm  >= ? "

		 // AND NumOfGSs = :numGS AND NumOfSTs = :numSTs AND NumOfTrns = :numRecs)
		// $$$TRACE(sqlStr)
		set rset = ##class(%SQL.Statement).%ExecDirect(,sqlStr, InterchangeCtrlNum, InterchangeReceiverID, InterchangeSenderID, grpCtrlNum, applicationReceiversCode, applicationSendersCode, recDt) 

		IF rset.%SQLCODE=0 {
			Do rset.%Next()
		    $$$TRACE("Count: " _ rset.%ROWCOUNT _ "Doc Id = " _ rset.ID)
		    set tPrelationDocumentId = rset.ID  
		    }
		ELSE {
		    $$$TRACE(sqlStr _ ": InterchangeControlNumber = "_ InterchangeCtrlNum _" AND InterchangeReceiverID  = " _ InterchangeReceiverID _" AND InterchangeSenderID = " _ InterchangeSenderID )
			 $$$TRACE("AND GroupControlNumber = " _ grpCtrlNum _" AND  ApplicationReceiversCode = " _ applicationReceiversCode _ " AND ApplicationSendersCode  = " _ applicationSendersCode) 
			 $$$TRACE("AND NumOfGSs = " _ numGS _" AND NumOfSTs = " _ numSTs _" AND NumOfTrns = " _ numRecs)

		    $$$TRACE("No records found, SQLCODE=" _ SQLCODE )		    
		}


	 } catch err
	 {
		 set tSC= $$$ERROR($$$EnsEDIX12ErrGeneral, "Exception in IsDuplicate: " _ err)
	 }
 }
 else
 {
	 $$$TRACE("Invalid doc type")
	 set tSC= $$$ERROR($$$EnsEDIX12ErrGeneral, "Doctype is not valid: "_ x12Doc.DocType)
 }
 $$$TRACE("IsDuplicate return ID: " _ tPrelationDocumentId)
 return tSC

	Set x12Doc.FunctionalGroups(k1)=k1
	set numRecs = 0
	set numSTs = 0
	set stTranCode = ""
	set k2=""
		If ""=k1.DocType {
			Set tDocType = k1.resolveChildDocType()
			Set tSC =k1.PokeDocType(tDocType)
		}
		set tSC = x12Doc.FunctionalGroups(k1).BuildMap()

 		Set k2=x12Doc.FunctionalGroups(k1).NextChild(k2,x12Doc.FunctionalGroups(k1).GetSegmentIndex("TransactionSetDocsRef",.tSCTrans))
 		while ($IsObject(k2))
 		{
			$$$TRACE( "k2: " _ k2.%Id() _", # of segs: " _ k2.SegCountGet())
			Set x12Doc.FunctionalGroups(k1).TransactionSets(k2)=k2
			If ""=k2.DocType {
				Set tDocType = k2.resolveChildDocType()
				Set tSC =k2.PokeDocType(tDocType)
			}
			set stTranCode = x12Doc.FunctionalGroups(k1).TransactionSets(k2).GetValueAt("ST:TransactionSetIdentifierCode",,,1)
			set numSTs = numSTs + 1
			set transactionCode = stTranCode
			FOR seg=1:1:k2.SegCountGet()
			{
				set recType = k2.GetValueAt(seg_":0")

				if ((stTranCode = "271") &&(recType = "EB"))
				{
					set numRecs = numRecs + 1
					// $$$TRACE(stTranCode _", " _ k2.GetSegmentPath(seg) _ "- " _ seg_": " _recType)
				}
				elseif ((stTranCode = "270") &&(recType = "EQ"))
				{
					set numRecs = numRecs + 1
					// $$$TRACE(stTranCode _", " _ k2.GetSegmentPath(seg) _ "- " _ seg_": " _recType)
				}
				elseif ((stTranCode = "837") &&(recType = "CLM"))
				{
					set numRecs = numRecs + 1
					// $$$TRACE(stTranCode _", " _ k2.GetSegmentPath(seg) _ "- " _ seg_": " _recType)
				}
				elseif ((stTranCode = "835") &&(recType = "CLP"))
				{
					set numRecs = numRecs + 1
					// $$$TRACE(stTranCode _", " _ k2.GetSegmentPath(seg) _ "- " _ seg_": " _recType)
				}
				elseif ((stTranCode = "999") && ((recType = "IK5")|| (recType = "AK9")))
				{
					set numRecs = numRecs + 1
					// $$$TRACE(stTranCode _", " _recType _", Stat: " _ k2.GetValueAt(seg_":1"))
					if (k2.GetValueAt(seg_":1") '= "A")
					{
						$$$TRACE("Original record " _ x12Doc.OriginalDocId _ " has errors " _ k2.TopParentId)
						set parentErrorMsg = parentErrorMsg _ " " _ recType _ "*" _ k2.GetValueAt(seg_":1") _ "*" _ k2.GetValueAt(seg_":2")
					}
				}
				else
				{
					// $$$TRACE("Unknown codes: " _ stTranCode _", " _ k2.GetSegmentPath(seg) _ "- " _ seg_": " _recType)
				}
			}
			Set k2=x12Doc.FunctionalGroups(k1).NextChild(k2,x12Doc.FunctionalGroups(k1).GetSegmentIndex("TransactionSetDocsRef",.tSCTrans))
			// $$$TRACE("Next FunctionalGroups:" _ k2)
 		}
 		WRITE !, stTranCode _ " - STs: " _ numSTs _ ", " _ stTranCode _ " SUBMISSION records: " _ numRecs

	set tsc= $$$ERROR("Interchange Link Not found")
	set errorMsg = " Interchange Link Not found: "_ senderId _ "->" _ receiverId _ ", Version: " _ version _ ", Mode: " _ mode _ ", Direction: " _ direction
	$$$TRACE( "-- Find ISA Interchge Link --" _ senderId _ "->" _ receiverId _ ", Version: " _ version _ ", Mode: " _ mode _ ", Direction: " _ direction)

	&sql(DECLARE WPCursor CURSOR FOR 
        select r.ID, r.name 
		from IHC_TPManage.TRADELINKS r, 
		IHC_TPManage.TPIDS t1,
		IHC_TPManage.TPIDS t2,
		IHC_TPManage.TRANSACTIONTYPES tr
		where
		r.IsaSenderId = t1.ID
		and r.IsaReceiverId = t2.ID
		and r.TRANSTYPE = tr.ID
		and t1.TPID = :senderId
		and t2.TPID = :receiverId
		and tr.VERSION = :version
		and r.Mode = :mode
		and r.Direction = :direction
		and r.Active = 1
		)
   &sql(OPEN WPCursor)
        if (SQLCODE'=0) RETURN tsc
   FOR 
   { 
   		&sql(FETCH WPCursor into :id, :relNm)
   		WRITE !, "ItfFind InterchageLink :SQLCODE: " _ SQLCODE
        if (SQLCODE = 0)
        {
	        $$$TRACE( id _", :" _ relNm)
	        set errorMsg = " FOUND TRADELINK for ISA: " _ relNm _", " _ senderId _", " _ receiverId _", " _ docType _", " _ version

	        set tpObj.IsaRelationID = id
	        set tpObj.ISARELATIONSHIPNAME = relNm
	        set tsc= $$$OK
	        QUIT
        }
        else
        {

        	if ('..ItfFindTPIDS(senderId, .tpMsg))
        	{
				set errorMsg = errorMsg _ tpMsg
        	}

			if ('..ItfFindTPIDS(receiverId, .tpMsg))
			{
				set errorMsg = errorMsg _ tpMsg
			}

			QUIT

        }
   }
    &sql(CLOSE WPCursor)

    return tsc

set sessionId = "" $$$TRACE( "-- GetSessionId: " _ msgBodyId)
try { &sql(DECLARE WPCursor CURSOR FOR SELECT TOP 1 SessionId FROM Ens.MessageHeader where MessageBodyId= :msgBodyId)
&sql(OPEN WPCursor) QUIT:(SQLCODE'=0) FOR { &sql(FETCH WPCursor into :sesId) QUIT:SQLCODE set sessionId = sesId $$$TRACE( "-- FETCH " _ msgBodyId _", " _ sesId) } &sql(CLOSE WPCursor)
} catch err { $$$LOGERROR("SQL error: " _ err) } return sessionId

 try {
	 set retStr = ""
	 $$$TRACE("Resend: " _ destComp _ ", msgId: " _ msgId)
	 set $NAMESPACE = nmSp

	 set HeadOfQueue = 0
	 if (headQ = "true")
	 {
		set HeadOfQueue = 1
	 }
	 set Key  = "KEY"
	 set num = 0


		Set tSC=##class(Ens.MessageHeader).ResendDuplicatedMessage(msgId,.tNewHeaderId,destComp,,,HeadOfQueue)
		If ($$$ISERR(tSC)) {
			Set errText = $System.Status.GetErrorText(tSC)
			set retStr =  "Error: " _ errText _ ", Ens.MessageHeader.Id: " _ tMsgId			
		}

		Else {
			set retStr =  "RESENT: Ens.MessageHeader.Id: " _ msgId _ ", New Id: " _ tNewHeaderId 
			Set ^CacheTemp.ResendIDs(Key,msgId,"sc") = "OK"
			Set ^CacheTemp.ResendIDs(Key,msgId,"new") = tNewHeaderId
		}


   } catch err
	    {
		    set retStr = "Exception: " _ err.message
	    }
	return retStr

try {
set x12Doc = ##class(EnsLib.EDI.X12.Document).%OpenId(x12Id)
return GetAckDetails(x12Doc, retStr , contact )
 } catch err
{
	set retStr = x12Id _ " Exception: code: " _ err.Code _ ",  location: " _ err.Location
}

	set tsc= $$$ERROR("Interchange Relation Not found")
	set onm = $NAMESPACE
	if ($SYSTEM [ "PROVIDER")
	{
		set $NAMESPACE = "RCOEDI"
	}
	else
	{		
		set $NAMESPACE = "EDIPAYER"
	}
	set errorMsg = " Interchange Relation Not found: "_ senderId _ "->" _ receiverId _ ", Version: " _ version _ ", Mode: " _ mode _ ", Direction: " _ direction
	$$$TRACE( "-- Find ISA InterchgRelation --" _ senderId _ "->" _ receiverId _ ", Version: " _ version _ ", Mode: " _ mode _ ", Direction: " _ direction)

	&sql(DECLARE WPCursor CURSOR FOR 
        select r.ID, r.name 
		from IHC_TPManage.TRADELINKS r, 
		IHC_TPManage.TPIDS t1,
		IHC_TPManage.TPIDS t2,
		IHC_TPManage.TRANSACTIONTYPES tr
		where
		r.IsaSenderId = t1.ID
		and r.IsaReceiverId = t2.ID
		and r.TRANSTYPE = tr.ID
		and t1.TPID = :senderId
		and t2.TPID = :receiverId
		and tr.VERSION = :version
		and r.Mode = :mode
		and r.Direction = :direction
		AND tr.ID = r.TRANSTYPE
		and r.Active = 1
		)
   &sql(OPEN WPCursor)
        if (SQLCODE'=0) 
        {
	        WRITE !, "Open: " _ SQLCODE
        	RETURN tsc
        }
   FOR 
   { 
   		&sql(FETCH WPCursor into :id, :relNm)
        if SQLCODE '= 0
        { 
        	if ('..ItfFindTPIDS(senderId, .tpMsg))
        	{
				set errorMsg = errorMsg _ tpMsg
        	}

			if ('..ItfFindTPIDS(receiverId, .tpMsg))
			{
				set errorMsg = errorMsg _ tpMsg
			}

			QUIT
        }
        $$$TRACE( id _", :" _ relNm)
        set errorMsg = " FOUND relationship for ISA: " _ relNm _", " _ senderId _", " _ receiverId _", " _ version

        set lnkInfo = id _"," _ relNm
        set tsc= $$$OK
   }
    &sql(CLOSE WPCursor)
    set $NAMESPACE = onm
    return tsc

	try {

    set ak9Err = "", ik3Str = "", ik4Str = "", errStr = ""
    set retStr = "", contact= "", origSeg = ""
    WRITE !, "GetAckDetails: " _ x12Doc.DocType _", RawContent size:" _ $L(x12Doc.RawContent) _", Inbound X12 data: " _ x12Doc.OriginalDocId
  if (x12Doc.%IsA("EnsLib.EDI.X12.Document"))
  {	    
	  Set tSC=1
	  set numRecs = 0
	  set x12Doc.DocType = "HIPAA_5010:Interchange"

	   set InterchangeSenderID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeSenderID"), "<>W")
	   set InterchangeReceiverID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeReceiverID"), "<>W")
	   set InterchangeCtrlNum = x12Doc.GetValueAt("ISA:InterchangeControlNumber")

	   if ($F(InterchangeSenderID, "HT000015-0") <1)
	   {
	   		set contact = ..GetContactInfo(	InterchangeSenderID)
	   }
	   if ($F(InterchangeReceiverID, "HT000015-0") <1)
	   {
	   		set contact = contact _ ..GetContactInfo(InterchangeReceiverID)
	   }
	   set seg = x12Doc.FindSegment("TA1", .ind, .stat)
	   if ( ($$$ISOK(stat)) && ($IsObject(seg)))	  				
	   {
		   $$$TRACE("TA1") 
		   set ta04 = seg.GetValueAt("4") 
		   set ta05 = seg.GetValueAt("5")
		   Do ..ItfLookup("IHC.ITF.ITFCOMMON.TA1", ta05, .retVal)
		   set retStr = "Data Error: TA1 error" _ $CHAR(13) _$CHAR(10) _ retVal _  $CHAR(13) _$CHAR(10) _ "TA014:105:" _ ta04 _":" _ ta05
	   }
	   else
	   {
		set errList = ##class(%ListOfObjects).%New()

		set GSCounter = x12Doc.ChildCount
		for gsInt=1:1:GSCounter
    	{ 
        	#dim individualGroup As EnsLib.EDI.X12.Document
        	set individualGroup = x12Doc.getNthChild(gsInt,2)

			WRITE !, "# of STs: " _ individualGroup.ChildCount

		  	FOR stInd=1:1:individualGroup.ChildCount

		  	{

				set ik3Str = "", ik4Str="", errNum = 1, segNum=0, segErrCode = 0, segErrStr ="", x12Data = ""
				set errDet = ""

				set isaGsInfo = "ACK for ISA: "  _ InterchangeSenderID _" -> " _ InterchangeReceiverID _ ": CtrlNum: " _ InterchangeCtrlNum _ ": Group CtrlNum: " _ individualGroup.GetValueAt("GS:GroupControlNumber")
				$$$TRACE( isaGsInfo)

				#dim STRecord As EnsLib.EDI.X12.Document 

			  	set STRecord=individualGroup.getNthChild(stInd,2)

			  	set STRecord.DocType = "HIPAA_5010:999"


				  WRITE !, gsInt _". " _ stInd _ "- Parse999::: ST Segement CountGet: " _ STRecord.SegCountGet() 
				  set akStr = "", ikStr = "", stNum = 0, firstAK2 = 1, refTransType = ""
				  set refTransType = ""
				  FOR ind=1:1:STRecord.SegCountGet()
				  {
						set numRecs = numRecs + 1


						set segPath = STRecord.GetSegmentPath(ind, .stat)	
		  				set segVal = STRecord.GetValueAt(segPath,, .stat)
		  				set recType = STRecord.GetValueAt(segPath_":0")
		  				// WRITE !, segPath _": " _ segVal

						if (recType = "AK2")
						{
							set msgTrans = STRecord.GetValueAt(segPath_":1")
							set stNum = $PIECE(segVal, x12Doc.ElementSeparator , 3)
							set refTransType = $PIECE(segVal, x12Doc.ElementSeparator , 2)
							WRITE !, "Ak2: " _ refTransType _", " _ stNum
						}

						if (recType = "IK3")
						{

							 if (ikStr '= "")
							 {
								 WRITE !, "IK3 - Create IHC.ITF.ITFCOMMON.X12ErrorDetails: " _ segNum
								 set errDet = ##class(IHC.ITF.ITFCOMMON.X12ErrorDetails).%New()

									Do errList.Insert(errDet)
									set errDet.stNum = stNum
									set errDet.segNum = segNum
									set errDet.x12Data = "TBD" // x12Data
									set errDet.segErrCode = segErrCode
									set errDet.segErrStr = ikStr
									set ikStr = ""
							 }
							set segNum = 	$PIECE(segVal, x12Doc.ElementSeparator , 3)
							if ($PIECE(segVal, x12Doc.ElementSeparator , 4) > 0)
							{
								set ikStr = ikStr _ $CHAR(13) _ " Loop: " _ $PIECE(segVal, x12Doc.ElementSeparator , 4) _", "
							}
							set ikStr = ikStr _ $PIECE(segVal, x12Doc.ElementSeparator , 2)
							set segErrCode = $PIECE(segVal, x12Doc.ElementSeparator , 5)
							Do ..ItfLookup("IHC.ITF.Process.Bpl.IK3Values", segErrCode, .retVal)


						  	set segVal = ..GetFullSegment(x12Doc.OriginalDocId, segNum, stNum)
						  	WRITE !, segNum _", " _ stNum _ ": " _ segVal

						  	set ikStr = ikStr _ ": " _ retVal // _ " Segment Data: " _ segVal
			  				WRITE !, "IK3 -" _ 	ikStr				


						}
						elseif (recType = "IK4")
						{
							WRITE !, "IK4 - Create IHC.ITF.ITFCOMMON.X12ErrorDetails: " _ segNum
							set errDet = ##class(IHC.ITF.ITFCOMMON.X12ErrorDetails).%New()

							Do errList.Insert(errDet)

							set errDet.stNum = stNum
							set errDet.segNum = segNum
							set errDet.x12Data = "TBD" // x12Data
							set errDet.segErrCode = segErrCode
							set errDet.segErrStr = ikStr

							set ik4Err = $PIECE(segVal, x12Doc.ElementSeparator , 4)
							Do ..ItfLookup("IHC.ITF.Process.Bpl.IK4Values", ik4Err, .retVal)
							set errDet.eleErrCode = ik4Err
							set errDet.eleErrStr = retVal
							set errDet.eleNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)

							set errNum = errNum + 1
							set ikStr = ""
						}
						elseif (recType = "IK5")
						{
							WRITE !, "Type of errors: " _ $PIECE(segVal, x12Doc.ElementSeparator , 3)

						}

						elseif (recType = "AK9")
						{
							set seg3Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
			  			  	Do ..ItfLookup("IHC.ITF.Process.Bpl.AkCodeLookup", seg3Val, .retVal)
						  	set ak9Err = "Functional Group Response: " _ seg3Val _" (" _ retVal _"): # Transaction Sets: " _ $PIECE(segVal, x12Doc.ElementSeparator , 3) _ ": # Received: " _ $PIECE(segVal, x12Doc.ElementSeparator , 4) _ ": # Accept: " _ $PIECE(segVal, x12Doc.ElementSeparator , 5)

						}					

					}
		  		}
    		 }
		    }
		    set retStr = ak9Err

		    // Store to WF table
		    if (storeRec)
	    	{
		    	$$$TRACE( "Store error in IHC_ITF_ITFCOMMON_X12.WorkFlow")
		    	for i=1:1: errList.Count()
			  	{
				  $$$TRACE( "Segment # " _errList.GetAt(i).segNum _", " _ errList.GetAt(i).segErrStr _", Element # " _ errList.GetAt(i).eleNum _", Error: " _ errList.GetAt(i).eleErrStr _". X12= "_ errList.GetAt(i).x12Data _" ->" _ """" _ $PIECE(errList.GetAt(i).x12Data, "*", errList.GetAt(i).eleNum+1)_ """")
				  WRITE "errList: Segment # " _errList.GetAt(i).segNum _", " _ errList.GetAt(i).segErrStr _", Element # " _ errList.GetAt(i).eleNum _", Error: " _ errList.GetAt(i).eleErrStr _". X12= "_ errList.GetAt(i).x12Data _" ->" _ """" _ $PIECE(errList.GetAt(i).x12Data, "*", errList.GetAt(i).eleNum+1)_ """"
			  	}


			  set dtTm = $ZDATETIME($HOROLOG,3, 1)
			  set x12Data = x12Doc.OutputToString()
			  set origX12id = x12Doc.OriginalDocId
			  WRITE !, InterchangeReceiverID _", " _ InterchangeSenderID _", " _ x12Doc.OriginalDocId
			  WRITE !, "msgTrans: " _ msgTrans
			  set sqlStr = "INSERT into IHC_ITF_ITFCOMMON_X12.WorkFlow " _
			  " (InterchangeReceiverID, InterchangeSenderID, TransactionType, WorkStatus, ErrorType, Error, " _
			  " AssignedUser, CreateDtTm,  OrigX12Id, SessionId) " _
			  " values (?,?,?,?,?,?,?,?,?,?)"
			  #dim rset As %SQL.StatementResult
			  set rset = ##class(%SQL.Statement).%ExecDirect(, .sqlStr, InterchangeReceiverID, 
			  InterchangeSenderID, msgTrans,  "New", "Data", retStr, "System", dtTm,  origX12id, $$$JobSessionId)
			  $$$TRACE( "SQL code: " _ rset.%SQLCODE)
			  if (rset.%SQLCODE < 0)
			  {
				  return $$$ERROR($$$GeneralError, "SQL failed: " _ rset.%SQLCODE _"; " _ rset.%Message)
			  }

			  set id = rset.%ROWID
			  $$$TRACE( $NAMESPACE _ " - Inserted to  WorkFlow. ID: " _ id )
			  WRITE !, "WorkFlow ID: " _ id _", " _ msgTrans 
			  set obj = ##class(IHC.ITF.ITFCOMMON.X12.WorkFlow).%OpenId(id)
			  if ($IsObject(obj))
			  {
			      WRITE !, "Insert errList #" _ errList.Count() 


 				  WRITE !, errList.GetAt(i).segNum _";segErrCode " _ errList.GetAt(i).segErrCode _"; segErrStr " _  errList.GetAt(i).segErrStr _"; eleNum " _ errList.GetAt(i).eleNum _"; eleErrCode " _  errList.GetAt(i).eleErrCode

 			      WRITE !, errList.GetAt(i).eleErrStr _"; x12Data  " _ errList.GetAt(i).x12Data 

				  $$$TRACE( "Insert errList #" _ errList.Count() )

					  for i=1:1: errList.Count()
					  {
						 if ($IsObject(errList.GetAt(i)))
				  		 {
					  		 WRITE !, errList.GetAt(i).segNum
						  		set stat = obj.ErrList.Insert(errList.GetAt(i))
						  		$$$TRACE( "insert segNum: " _ errList.GetAt(i).segNum _": " _ stat)
				  		 }
						  //
					  }
					  set stat = obj.%Save()
					  $$$TRACE( " ErrList.Count: " _ obj.ErrList.Count())
					  WRITE !, "IHC.ITF.ITFCOMMON.X12.WorkFlow ErrList.Count: " _ obj.ErrList.Count() _" Save: " _ stat


				  WRITE !, "Segment # " _errList.GetAt(i).segNum _" " _ errList.GetAt(i).segErrStr _", Element # " _ errList.GetAt(i).eleNum _" " _ errList.GetAt(i).eleErrStr _". X12= "_ errList.GetAt(i).x12Data _" ->" _ """" _ $PIECE(errList.GetAt(i).x12Data, "*", errList.GetAt(i).eleNum+1)_ """"
			  }
	    	}
	    }
	    else
	    {
		    $$$TRACE( "Not EnsLib.EDI.X12.Document")
	    }



    } catch err
	{
		set retStr = x12Doc _ " Exception: code: " _ err.Code _ ",  location: " _ err.Location
	}
   return $$$OK

  set x12Doc = ##class(EnsLib.EDI.X12.Document).%OpenId(x12Id)
  set segRec = ""
  if (x12Doc.%IsA("EnsLib.EDI.X12.Document"))
  {	    
	  Set k1="",tSC=1,k2=""
