	  " (InterchangeReceiverID, InterchangeSenderID, TransactionType, TransactionVersion, WorkStatus, " _
	  " ErrorType, Error, WorkUser, CreateDtTm, x12Data, OrigX12Id, SessionId) " _
	  " values (?,?,?,?,?,?,?,?,?,?,?)"
