	  set rset = ##class(%SQL.Statement).%ExecDirect(, .sqlStr, interchangeReceiverID, interchangeSenderID, 
	  msgTrans, msgTransVer, "New", "TP", errStr, $USERNAME, dtTm, str, 0, $$$JobSessionId)
	  WRITE "SQL code: " _ rset.%SQLCODE
