 set ConfigName = "AutoIsaGs"
 set ctrlVerNum = "00501"
 set lnkObj = ##class(IHC.TPManage.TRADELINKS).%OpenId(lnkNum)
 // WRITE !, lnkObj.NAME
 set transSubType = ""
 set functionalGroupHeader = ""

 if ('$IsObject(lnkObj))
 {
	 $$$LOGERROR("Link not found: " _ lnkNum)
	 QUIT $$$ERROR($$$EnsErrGeneral , "Link not found: " _ lnkNum)
 }
 // WRITE !, lnkObj.IsaSenderId.TPID _"->" _ lnkObj.IsaReceiverId.TPID
 //  WRITE !, lnkObj.GsSenderId.TPID _"->" _ lnkObj.GsReceiverId.TPID
 // WRITE !, lnkObj.TRANSTYPE.NAME _": " _ lnkObj.TRANSTYPE.TransactionSetId _", " _ lnkObj.TRANSTYPE.VERSION

 if (lnkObj.TRANSTYPE.VERSION = "V5010X222A1")
 {
 	set transSubType ="P"
 }
  elseif (lnkObj.TRANSTYPE.VERSION = "V5010X223A2")
  {
 	set transSubType ="I"
  }
  elseif (lnkObj.TRANSTYPE.VERSION = "V5010X224A2")
  {
 	set transSubType ="D"
  }

 if (lnkObj.TRANSTYPE.TransactionSetId = "271")
 {
 	set functionalGroupHeader = "HB" //Eligibility, Coverage or Benefit Information (271)
 }
 elseif (lnkObj.TRANSTYPE.TransactionSetId = "277")
 {
 	set functionalGroupHeader = "HN" //Health Care Claim Status Notification (277)
 }
 elseif (lnkObj.TRANSTYPE.TransactionSetId = "276")
 {
 	set functionalGroupHeader = "HR" //Health Care Claim Status Request (276)
 }
 elseif (lnkObj.TRANSTYPE.TransactionSetId = "270")
 {
 	set functionalGroupHeader = "HS" //Eligibility, Coverage or Benefit Inquiry (270)
 }
 elseif (lnkObj.TRANSTYPE.TransactionSetId = "278")
 {
 	set functionalGroupHeader = "HI" //Health Care Services Review Information (278)
 }
 elseif (lnkObj.TRANSTYPE.TransactionSetId = "837")
 {
 	set functionalGroupHeader = "HC" //Health Care Claim (837)
 }
 elseif (lnkObj.TRANSTYPE.TransactionSetId = "835")
 {
 	set functionalGroupHeader = "HP" //Health Care Claim Payment/Advice (835)
 }
 elseif (lnkObj.TRANSTYPE.TransactionSetId = "820")
 {
 	set functionalGroupHeader = "RA" //Payment Order/Remittance Advice (820)
 }

 Set curDTM=$ZDATETIME($HOROLOG,8, 1)

 set ctrlNum = ..getControlNumber(ConfigName, lnkObj.IsaSenderId.TPID, lnkObj.IsaReceiverId.TPID, lnkObj.TRANSTYPE.TransactionSetId)
 set isaCtrlNum =  "0" _ ctrlNum
 FOR i=$L(isaCtrlNum )+1:1:9
  {
    set isaCtrlNum =  "0" _ isaCtrlNum 
  }
 // set target = ##class(EnsLib.EDI.X12.Document).%New()
 // Get separators

 set ^sep("ElementDelimiter") = ""
 set sepStr = ""
 for i=1:1:lnkObj.customProp.Size
 {

	 // $$$TRACE( lnkObj.customProp.GetAt(i).Key _"= " _  lnkObj.customProp.GetAt(i).Value)
	 if ("Separators" = lnkObj.customProp.GetAt(i).Key)
	 {
		 set sepLen = $LENGTH(lnkObj.customProp.GetAt(i).Value, ";")
		 for j=1:1:sepLen
		 {
			 set hexVal = $ZSTRIP($PIECE($PIECE(lnkObj.customProp.GetAt(i).Value, ";", j), ":", 2)  , "*W")

			 if (hexVal [ "0x")
			 {
				// $$$TRACE( $PIECE($PIECE(lnkObj.customProp.GetAt(i).Value, ";", j), ":", 1) _"= " _ $CHAR($SYSTEM.Util.HexToDecimal($E(hexVal,3,4))))
			    set ^sep($ZSTRIP($PIECE($PIECE(lnkObj.customProp.GetAt(i).Value, ";", j), ":", 1), "*W")) = $CHAR($SYSTEM.Util.HexToDecimal($E(hexVal,3,4)))
			 }
		 }
	 }
 }
 if (^sep("ElementDelimiter") '= "")
 {
 	set sepStr = $GET(^sep("ElementDelimiter")) _ $GET(^sep("SegmentDelimiter")) _ $GET(^sep("RepeatingSeparator"))
 }

 set target.Separators = $SELECT($L(sepStr) = 3:sepStr, 1:"|~^")

 set target.DocType = "HIPAA_5010:Interchange:Group:" _ lnkObj.TRANSTYPE.TransactionSetId _ transSubType

 // Interchange Control Header (ISA) values
 Do target.SetValueAt("00","ISA:AuthorizationInformationQual","set","")
 Do target.SetValueAt("          ", "ISA:AuthorizationInformation","set","")
 Do target.SetValueAt("          ", "ISA:SecurityInformation","set","")
 Do target.SetValueAt("00","ISA:SecurityInformationQualifier","set","")
 Do target.SetValueAt("ZZ","ISA:InterchangeIDQualifier","set","")
 Do target.SetValueAt(lnkObj.IsaSenderId.TPID,"ISA:InterchangeSenderID","set","")
 Do target.SetValueAt("ZZ","ISA:InterchangeIDQualifier2","set","")
 Do target.SetValueAt(lnkObj.IsaReceiverId.TPID,"ISA:InterchangeReceiverID","set","")
 Do target.SetValueAt($E(curDTM,3,8),"ISA:InterchangeDate","set","")
 Do target.SetValueAt($E($REPLACE(curDTM,":",""),10,13),"ISA:InterchangeTime","set","")
 Do target.SetValueAt(ctrlVerNum,"ISA:InterchangeControlVersionNum","set","")	
 Do target.SetValueAt(isaCtrlNum,"ISA:InterchangeControlNumber","set","")
 Do target.SetValueAt("0","ISA:AcknowledgmentRequested","set","")
 Do target.SetValueAt("P","ISA:UsageIndicator","set","")


 Do target.SetValueAt("1","IEA:NumberofIncludedFunctionalGr","set","")
 Do target.SetValueAt(isaCtrlNum,"IEA:InterchangeControlNumber","set","")	

 // New Functional Group

 Set target.FunctionalGroups(1)=##class(Ens.X12.FunctionSet).X12NewFunctionalGroup(target,"Group")
 Do target.FunctionalGroups(1).SetValueAt(functionalGroupHeader,"GS:FunctionalIdentifierCode", "set","") 
 Do target.FunctionalGroups(1).SetValueAt(lnkObj.GsSenderId.TPID,"GS:ApplicationSendersCode","set","") 
 Do target.FunctionalGroups(1).SetValueAt(lnkObj.GsReceiverId.TPID,"GS:ApplicationReceiversCode","set","")
 Do target.FunctionalGroups(1).SetValueAt($E(curDTM,1,8),"GS:Date","set","")
 Do target.FunctionalGroups(1).SetValueAt($E($REPLACE(curDTM,":",""),10,13),"GS:Time","set","")

 Do target.FunctionalGroups(1).SetValueAt(ctrlNum,"GS:GroupControlNumber", "set","") 
 Do target.FunctionalGroups(1).SetValueAt(ctrlNum,"GE:GroupControlNumber", "set","") 

 Do target.FunctionalGroups(1).SetValueAt("X","GS:ResponsibleAgencyCode", "set","") 
 Do target.FunctionalGroups(1).SetValueAt(lnkObj.TRANSTYPE.VERSION,"GS:VersionReleaseIndustryIdenti", "set","") 

 // New TransactionSet
 Set target.FunctionalGroups(1).TransactionSets(1) = ##class(Ens.X12.FunctionSet).X12NewTransactionSet(target.FunctionalGroups(1), lnkObj.TRANSTYPE.TransactionSetId _ transSubType)

 Do target.FunctionalGroups(1).TransactionSets(1).SetValueAt(lnkObj.TRANSTYPE.TransactionSetId,"ST:TransactionSetIdentifierCode","set","")
 Do target.FunctionalGroups(1).TransactionSets(1).SetValueAt("0001","ST:TransactionSetControlNumber","set","")
 QUIT $$$OK



// Complete the Transaction Set and Functional Group Loops
Set tSC1=target.FunctionalGroups(1).TransactionSets(1).SetValueAt(##class(Ens.X12.FunctionSet).X12CompleteTrailerAndReturnClear(target.FunctionalGroups(1).TransactionSets(1),1),"ST","set","") 

Set target.FunctionalGroups(1)=##class(Ens.X12.FunctionSet).X12CompleteTrailerAndReturnClear(target.FunctionalGroups(1),1)

	set x12Doc.DocType = "HIPAA_5010:Interchange:Group"

   set errStr = ""
   if (x12Doc.%Extends("EnsLib.EDI.X12.Document"))
	 {
		   Set tSC =x12Doc.BuildMap()

		   set InterchangeCtrlNum = x12Doc.GetValueAt("ISA:InterchangeControlNumber")
		   set InterchangeSenderID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeSenderID"), "<>W")
		   set InterchangeReceiverID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeReceiverID"), "<>W")

	      /// $$$TRACE( "Parse999::: 999 for: "  _ ISA SenderID _" -> " _ ReceiverID _ ": CtrlNum: " _ InterchangeCtrlNum)
		  set individualGroup = x12Doc.getNthChild(1,2)

		  set isaGsInfo = "ACK for ISA: "  _ InterchangeSenderID _" -> " _ InterchangeReceiverID _ ": CtrlNum: " _ InterchangeCtrlNum _ ": Group CtrlNum: " _ individualGroup.GetValueAt("GS:GroupControlNumber")
		  // WRITE !, x12Doc.ElementSeparator  _", " _ x12Doc.ComponentSeparator 
		  set STRecord=individualGroup.getNthChild(1,2)
		  set transType = STRecord.GetValueAt("1:1",, .stat)

		  set STRecord.DocType = "HIPAA_5010:" _ transType
		  // $$$TRACE( "Parse999::: ST: " _  transType_ ", CountGet: " _ STRecord.SegCountGet() )
		  set akStr = "", ikStr = "", stNum = 0, firstAK2 = 1
		  set refTransType = ""
		  FOR ind=1:1:STRecord.SegCountGet()
		  {

			set segPath = STRecord.GetSegmentPath(ind, .stat)	
		  	set segVal = STRecord.GetValueAt(segPath,, .stat)
		  	// WRITE !, ind _". " _ segPath _"= " _ segVal

		  	if ($FIND(segVal,"AK2") = 4)
		  	{
  			  	set refTransType = $PIECE(segVal, x12Doc.ElementSeparator , 2)

			  	Do ..ItfLookup("IHC.ITF.Process.Bpl.AkTransSetlLookup", refTransType, .retVal)
			  	set stNum = $PIECE(segVal, x12Doc.ElementSeparator , 3)

				set akStr = refTransType _" (" _ retVal _"): TransactionSet CtrlNum: " _ stNum

		  	}
		  	elseif ($FIND(segVal,"IK5") = 4)
		  	{
  			  	set seg2Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
  			  	if (seg2Val '= "A")
  			  	{
				  	Do ..ItfLookup("IHC.ITF.Process.Bpl.AkCodeLookup", seg2Val, .retVal)
				  	set ik5Str = $CHAR(13) _  " => " _ retVal _  " (" _ seg2Val _")"
				  	if ($PIECE(segVal, x12Doc.ElementSeparator , 3) '= "") {
					   	set seg3Val = $PIECE(segVal, x12Doc.ElementSeparator , 3)
				  		Do ..ItfLookup("IHC.ITF.Process.Bpl.AkErrorLookup", seg3Val, .retVal)
				  		set ik5Str = ik5Str _ ": Error: "  _ retVal _" ("  _  seg3Val  _")"
				  	}	
				  	if (ikStr '= "")
				  	{
				  	   set ik5Str = ik5Str _ ": Details:" _ ikStr 
				  	}
				  	if (firstAK2 = 1)
				  	{
				  		set errStr = errStr _ isaGsInfo  _ $CHAR(13) _ akStr _" " _ ik5Str _" # "
				  		set firstAK2 = 0
				  	}
				  	else
				  	{
					  	set errStr = errStr _ $CHAR(13) _ akStr _" " _ ik5Str _" # "
				  	}		  					
  			  	}

				set akStr = "", ikStr = ""
		  	}
		  	elseif ($FIND(segVal,"IK3") = 4)
		  	{		   
		  	    set segNum = 	$PIECE(segVal, x12Doc.ElementSeparator , 3)
				set ikStr = ikStr _ $CHAR(13) _ " Loop: " _ $PIECE(segVal, x12Doc.ElementSeparator , 4) _ ": Segment Num: " _ segNum _": " _ $PIECE(segVal, x12Doc.ElementSeparator , 2)
				Do ..ItfLookup("IHC.ITF.Process.Bpl.IK3Values", $PIECE(segVal, x12Doc.ElementSeparator , 5), .retVal)


			  	set segVal = ..GetSegment(origMsg, segNum, stNum)

			  	set ikStr = ikStr _ ": " _ retVal _". Inbound " _ refTransType _ " Segment Data: " _ segVal

		  	}
		  	elseif ($FIND(segVal,"IK4") = 4)
		  	{		   	

				Do ..ItfLookup("IHC.ITF.Process.Bpl.IK4Values", $PIECE(segVal, x12Doc.ElementSeparator , 4), .retVal)
				set eleData = $PIECE(segVal, x12Doc.ElementSeparator , 5)
			  	set ikStr = ikStr _ ": Element Position: " _ $PIECE(segVal, x12Doc.ElementSeparator , 2) _ ": Error: " _ retVal _ ": Element Data: " _ $SELECT(0=$L(eleData):"<NULL>", 1: eleData)

		  	}
		  	elseif ($FIND(segVal,"AK9") = 4)
		  	{
  			  	set seg3Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
  			  	Do ..ItfLookup("IHC.ITF.Process.Bpl.AkCodeLookup", seg3Val, .retVal)
			  	set ak9Str = "Functional Group Response: " _ seg3Val _" (" _ retVal _"): # Transaction Sets: " _ $PIECE(segVal, x12Doc.ElementSeparator , 3) _ ": # Received: " _ $PIECE(segVal, x12Doc.ElementSeparator , 4) _ ": # Accept: " _ $PIECE(segVal, x12Doc.ElementSeparator , 5)
			  	if (errStr = "")
			  	{
				  	set errStr = ak9Str
			  	}

		  	}
		  }
	 }
	 return errStr _"; " _ ak9Str

	set GSnum = 1, STnum = 1, retStr = "Segment: " _ segInd _" not found"

  if ( ($ISOBJECT(x12Doc)) && (x12Doc.%Extends("EnsLib.EDI.X12.Document")) )
  {

 	set GSCounter = x12Doc.ChildCount
       set mmId = $EXTRACT($ZDATE($HOROLOG, 8), 1, 6)

          set segX12Data = ""
          if ( GSnum <= GSCounter)
          { 
            set individualGroup = x12Doc.getNthChild(GSnum,2)
            set individualGroup.DocType = "HIPAA_5010:Group"


	        set STCounter = individualGroup.ChildCount 

	        #dim individualST As EnsLib.EDI.X12.Document

	        while ( STnum <= STCounter)
	        { 
	        	set individualST = individualGroup.getNthChild(STnum)
	        	set x12StCtrlNum = $PIECE(individualST.OutputToString(), individualST.ElementSeparator, 3)
	        	// $$$TRACE( "ST. " _ STnum _ ", Transaction: " _ $PIECE(individualST.OutputToString(), individualST.ElementSeparator, 2) _", Ctrl# " _ x12StCtrlNum)
	        	if ( (stCtrlNum = x12StCtrlNum ) && (segInd <= individualST.SegCount))
	        	{
		        	return individualST.GetValueAt(segInd)
	        	}
	        	Do $INCREMENT(STnum)
	        }
          }
  }
  return retStr

	set msgTrans ="", msgTransVer ="", retStr="", contact="" //  errList As %ListOfObjects, 

	try {

    set ak9Err = "", ik3Str = "", ik4Str = "", errStr = ""
    set retStr = "", contact= "", origSeg = ""
    WRITE !, "GetAckDetails: " _ x12Doc.DocType _", RawContent size:" _ $L(x12Doc.RawContent) _", Inbound X12 data: " _ $L(origX12Doc.RawContent)
  if (x12Doc.%IsA("EnsLib.EDI.X12.Document"))
  {	    
	  Set tSC=1
	  set numRecs = 0
	  set x12Doc.DocType = "HIPAA_5010:Interchange"

	   set InterchangeSenderID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeSenderID"), "<>W")
	   set InterchangeReceiverID = $ZSTRIP(x12Doc.GetValueAt("ISA:InterchangeReceiverID"), "<>W")
	   set InterchangeCtrlNum = x12Doc.GetValueAt("ISA:InterchangeControlNumber")

	   if ($F(InterchangeSenderID, "HT000015-0") <1)
	   {
	   		set contact = ..GetContactInfo(	InterchangeSenderID)
	   }
	   if ($F(InterchangeReceiverID, "HT000015-0") <1)
	   {
	   		set contact = contact _ ..GetContactInfo(InterchangeReceiverID)
	   }
	   set seg = x12Doc.FindSegment("TA1", .ind, .stat)
	   if ( ($$$ISOK(stat)) && ($IsObject(seg)))	  				
	   {
		   $$$TRACE("TA1") 
		   set ta04 = seg.GetValueAt("4") 
		   set ta05 = seg.GetValueAt("5")
		   Do ..ItfLookup("IHC.ITF.ITFCOMMON.TA1", ta05, .retVal)
		   set retStr = "Data Error: TA1 error" _ $CHAR(13) _$CHAR(10) _ retVal _  $CHAR(13) _$CHAR(10) _ "TA014:105:" _ ta04 _":" _ ta05
	   }
	   else
	   {
		set errList = ##class(%ListOfObjects).%New()

		set GSCounter = x12Doc.ChildCount
		for gsInt=1:1:GSCounter
    	{ 
        	#dim individualGroup As EnsLib.EDI.X12.Document
        	set individualGroup = x12Doc.getNthChild(gsInt,2)

			WRITE !, "# of STs: " _ individualGroup.ChildCount

		  	FOR stInd=1:1:individualGroup.ChildCount

		  	{

				set ik3Str = "", ik4Str="", errNum = 1, segNum=0, segErrCode = 0, segErrStr ="", x12Data = ""
				set errDet = ""

				set isaGsInfo = "ACK for ISA: "  _ InterchangeSenderID _" -> " _ InterchangeReceiverID _ ": CtrlNum: " _ InterchangeCtrlNum _ ": Group CtrlNum: " _ individualGroup.GetValueAt("GS:GroupControlNumber")
				$$$TRACE( isaGsInfo)

				#dim STRecord As EnsLib.EDI.X12.Document 

			  	set STRecord=individualGroup.getNthChild(stInd,2)

			  	set STRecord.DocType = "HIPAA_5010:999"


				  WRITE !, gsInt _". " _ stInd _ "- Parse999::: ST Segement CountGet: " _ STRecord.SegCountGet() 
				  set akStr = "", ikStr = "", stNum = 0, firstAK2 = 1, refTransType = ""
				  set refTransType = ""
				  FOR ind=1:1:STRecord.SegCountGet()
				  {
						set numRecs = numRecs + 1


						set segPath = STRecord.GetSegmentPath(ind, .stat)	
		  				set segVal = STRecord.GetValueAt(segPath,, .stat)
		  				set recType = STRecord.GetValueAt(segPath_":0")
		  				// WRITE !, segPath _": " _ segVal _", " _ recType

						if (recType = "AK2")
						{
							set msgTrans = STRecord.GetValueAt(segPath_":1")
							set stNum = $PIECE(segVal, x12Doc.ElementSeparator , 3)
							set refTransType = $PIECE(segVal, x12Doc.ElementSeparator , 2)
							WRITE !, "Ak2: " _ refTransType _", " _ stNum
						}

						if (recType = "IK3")
						{

							 if (ikStr '= "")
							 {
								 WRITE !, "IK3 - Create IHC.ITF.ITFCOMMON.X12ErrorDetails: " _ segNum
								 set errDet = ##class(IHC.ITF.ITFCOMMON.X12ErrorDetails).%New()

									Do errList.Insert(errDet)
									set errDet.stNum = stNum
									set errDet.segNum = segNum
									set errDet.x12Data = "TBD" // x12Data
									set errDet.segErrCode = segErrCode
									set errDet.segErrStr = ikStr
									set ikStr = ""
							 }
							set segNum = 	$PIECE(segVal, x12Doc.ElementSeparator , 3)
							if ($PIECE(segVal, x12Doc.ElementSeparator , 4) > 0)
							{
								set ikStr = ikStr _ $CHAR(13) _ " Loop: " _ $PIECE(segVal, x12Doc.ElementSeparator , 4) _", "
							}
							set ikStr = ikStr _ $PIECE(segVal, x12Doc.ElementSeparator , 2)
							set segErrCode = $PIECE(segVal, x12Doc.ElementSeparator , 5)
							Do ..ItfLookup("IHC.ITF.Process.Bpl.IK3Values", segErrCode, .retVal)


						  	set segVal = ..GetFullSegmentFromX12(origX12Doc, segNum, stNum)
						  	WRITE !, segNum _", " _ stNum _ ": " _ segVal

						  	set ikStr = ikStr _ ": " _ retVal // _ " Segment Data: " _ segVal
			  				WRITE !, "IK3 -" _ 	ikStr				


						}
						elseif (recType = "IK4")
						{
							WRITE !, "IK4 - Create IHC.ITF.ITFCOMMON.X12ErrorDetails: " _ segNum
							set errDet = ##class(IHC.ITF.ITFCOMMON.X12ErrorDetails).%New()

							Do errList.Insert(errDet)

							set errDet.stNum = stNum
							set errDet.segNum = segNum
							set errDet.x12Data = "TBD" // x12Data
							set errDet.segErrCode = segErrCode
							set errDet.segErrStr = ikStr

							set ik4Err = $PIECE(segVal, x12Doc.ElementSeparator , 4)
							Do ..ItfLookup("IHC.ITF.Process.Bpl.IK4Values", ik4Err, .retVal)
							set errDet.eleErrCode = ik4Err
							set errDet.eleErrStr = retVal
							set errDet.eleNum = $PIECE(segVal, x12Doc.ElementSeparator , 2)

							set errNum = errNum + 1
							set ikStr = ""
						}
						elseif (recType = "IK5")
						{
							WRITE !, "Type of errors: " _ $PIECE(segVal, x12Doc.ElementSeparator , 3)

						}

						elseif (recType = "AK9")
						{
							set seg3Val = $PIECE(segVal, x12Doc.ElementSeparator , 2)
			  			  	Do ..ItfLookup("IHC.ITF.Process.Bpl.AkCodeLookup", seg3Val, .retVal)
						  	set ak9Err = "Functional Group Response: " _ seg3Val _" (" _ retVal _"): # Transaction Sets: " _ $PIECE(segVal, x12Doc.ElementSeparator , 3) _ ": # Received: " _ $PIECE(segVal, x12Doc.ElementSeparator , 4) _ ": # Accept: " _ $PIECE(segVal, x12Doc.ElementSeparator , 5)

						}					

					}
		  		}
    		 }
		    }
		    set retStr = ak9Err

		    // Store to WF table
		    if (storeRec)
	    	{
		    	$$$TRACE( "Store error in IHC_ITF_ITFCOMMON_X12.WorkFlow")
		    	for i=1:1: errList.Count()
			  	{
				  $$$TRACE( "Segment # " _errList.GetAt(i).segNum _", " _ errList.GetAt(i).segErrStr _", Element # " _ errList.GetAt(i).eleNum _", Error: " _ errList.GetAt(i).eleErrStr _". X12= "_ errList.GetAt(i).x12Data _" ->" _ """" _ $PIECE(errList.GetAt(i).x12Data, "*", errList.GetAt(i).eleNum+1)_ """")
				  WRITE "errList: Segment # " _errList.GetAt(i).segNum _", " _ errList.GetAt(i).segErrStr _", Element # " _ errList.GetAt(i).eleNum _", Error: " _ errList.GetAt(i).eleErrStr _". X12= "_ errList.GetAt(i).x12Data _" ->" _ """" _ $PIECE(errList.GetAt(i).x12Data, "*", errList.GetAt(i).eleNum+1)_ """"
			  	}


			  set dtTm = $ZDATETIME($HOROLOG,3, 1)
			  set x12Data = x12Doc.OutputToString()

			  WRITE !, InterchangeReceiverID _", " _ InterchangeSenderID _", " _ origX12id
			  WRITE !, "msgTrans: " _ msgTrans
			  set sqlStr = "INSERT into IHC_ITF_ITFCOMMON_X12.WorkFlow " _
			  " (InterchangeReceiverID, InterchangeSenderID, TransactionType, WorkStatus, ErrorType, Error, " _
			  " AssignedUser, CreateDtTm,  OrigX12Id, SessionID) " _
			  " values (?,?,?,?,?,?,?,?,?)"
			  #dim rset As %SQL.StatementResult
			  set rset = ##class(%SQL.Statement).%ExecDirect(, .sqlStr, InterchangeReceiverID, 
			  InterchangeSenderID, msgTrans,  "New", "Data", retStr, "System", dtTm,  origX12id, $$$JobSessionId)
			  $$$TRACE( "SQL code: " _ rset.%SQLCODE)
			  if (rset.%SQLCODE < 0)
			  {
				  return $$$ERROR($$$GeneralError, "SQL failed: " _ rset.%SQLCODE _"; " _ rset.%Message)
			  }

			  set id = rset.%ROWID
			  $$$TRACE( $NAMESPACE _ " - Inserted to  WorkFlow. ID: " _ id )
			  WRITE !, "WorkFlow ID: " _ id _", " _ msgTrans 
			  set obj = ##class(IHC.ITF.ITFCOMMON.X12.WorkFlow).%OpenId(id)
			  if ($IsObject(obj))
			  {
			      WRITE !, "Insert errList #" _ errList.Count() 


 				  WRITE !, errList.GetAt(i).segNum _";segErrCode " _ errList.GetAt(i).segErrCode _"; segErrStr " _  errList.GetAt(i).segErrStr _"; eleNum " _ errList.GetAt(i).eleNum _"; eleErrCode " _  errList.GetAt(i).eleErrCode

 			      WRITE !, errList.GetAt(i).eleErrStr _"; x12Data  " _ errList.GetAt(i).x12Data 

				  $$$TRACE( "Insert errList #" _ errList.Count() )

					  for i=1:1: errList.Count()
					  {
						 if ($IsObject(errList.GetAt(i)))
				  		 {
					  		 WRITE !, errList.GetAt(i).segNum
						  		set stat = obj.ErrList.Insert(errList.GetAt(i))
						  		$$$TRACE( "insert segNum: " _ errList.GetAt(i).segNum _": " _ stat)
				  		 }
						  //
					  }
					  set stat = obj.%Save()
					  $$$TRACE( " ErrList.Count: " _ obj.ErrList.Count())
					  WRITE !, "IHC.ITF.ITFCOMMON.X12.WorkFlow ErrList.Count: " _ obj.ErrList.Count() _" Save: " _ stat


				  WRITE !, "Segment # " _errList.GetAt(i).segNum _" " _ errList.GetAt(i).segErrStr _", Element # " _ errList.GetAt(i).eleNum _" " _ errList.GetAt(i).eleErrStr _". X12= "_ errList.GetAt(i).x12Data _" ->" _ """" _ $PIECE(errList.GetAt(i).x12Data, "*", errList.GetAt(i).eleNum+1)_ """"
			  }
	    	}
	    }
	    else
	    {
		    $$$TRACE( "Not EnsLib.EDI.X12.Document")
	    }



    } catch err
	{
		set retStr = x12Doc _ " Exception: code: " _ err.Code _ ",  location: " _ err.Location
	}
   return retStr


set transType = ""	  		  		  
  if (version [ "5010X222A1")
	{
		set transType = "837P"
	}
	elseif (version [ "5010X223A2")
	{
		set transType = "837I"
	}
	elseif (version [ "5010X224A2")
	{
		set transType = "837D"
	}
	elseif (version [ "5010X214")
	{
		set transType = "277CA"
	}
	elseif (version [ "5010X279A1") 
	{
		set transType = "270"
	}
	elseif (version [ "5010X212") 
	{
		set transType = "276"
	}
	elseif (version [ "5010X221A1") 
	{
		set transType = "835"
	}
return transType

